SELECT "sk_dateid", "datevalue", "datedesc", "calendaryearid", "calendaryeardesc", "calendarqtrid", "calendarqtrdesc", "calendarmonthid", "calendarmonthdesc", "calendarweekid", "calendarweekdesc", "dayofweeknum", "dayofweekdesc", "fiscalyearid", "fiscalyeardesc", "fiscalqtrid", "fiscalqtrdesc", "holidayflag" FROM (SELECT TRY_CAST((CAST(b1.SK_DateID AS INT)) AS int) AS "sk_dateid", TRY_CAST((TRY_CAST(b1.DateValue AS DATE)) AS date) AS "datevalue", TRY_CAST((CAST(b1.DateDesc AS CHAR(20))) AS char(20)) AS "datedesc", TRY_CAST((b1.CalendarYearID) AS decimal(4)) AS "calendaryearid", TRY_CAST((CAST(b1.CalendarYearDesc AS CHAR(20))) AS char(20)) AS "calendaryeardesc", TRY_CAST((b1.CalendarQtrID) AS decimal(5)) AS "calendarqtrid", TRY_CAST((CAST(b1.CalendarQtrDesc AS CHAR(20))) AS char(20)) AS "calendarqtrdesc", TRY_CAST((b1.CalendarMonthID) AS decimal(6)) AS "calendarmonthid", TRY_CAST((CAST(b1.CalendarMonthDesc AS CHAR(20))) AS char(20)) AS "calendarmonthdesc", TRY_CAST((b1.CalendarWeekID) AS decimal(6)) AS "calendarweekid", TRY_CAST((CAST(REPLACE(b1.CalendarWeekDesc, '-', ' -') AS CHAR(20))) AS char(20)) AS "calendarweekdesc", TRY_CAST((b1.DayOfWeekNum) AS decimal(1)) AS "dayofweeknum", TRY_CAST((b1.DayOfWeekDesc) AS char(10)) AS "dayofweekdesc", TRY_CAST((b1.FiscalYearID) AS decimal(4)) AS "fiscalyearid", TRY_CAST((CAST(b1.FiscalYearDesc AS CHAR(20))) AS char(20)) AS "fiscalyeardesc", TRY_CAST((b1.FiscalQtrID) AS decimal(5)) AS "fiscalqtrid", TRY_CAST((CAST(b1.FiscalQtrDesc AS VARCHAR(20))) AS char(20)) AS "fiscalqtrdesc", TRY_CAST((TRY_CAST(b1.HolidayFlag AS BOOLEAN)) AS boolean) AS "holidayflag" FROM Date AS b1)
